import {defaults,normalizeSettings} from './engine.js';
export const clone=value=>structuredClone(value);
let nextPhotoId=0;
export function createPhoto(file,recipe){return {id:'photo-'+(++nextPhotoId),file,name:file.name,recipe:clone(recipe),settings:normalizeSettings(recipe.settings||defaults),intensity:100,undo:[],redo:[],width:0,height:0,meta:'',thumbnail:'',selected:true,status:'pending',error:'',revision:0,isDemo:false};}
export function snapshot(settings,intensity,recipe){return {settings:normalizeSettings(settings),intensity:Math.max(0,Math.min(100,Number(intensity)||0)),recipe:clone(recipe)};}
export function copyTreatment(photo){return snapshot(photo.settings,photo.intensity,photo.recipe);}
export function pasteTreatment(photo,treatment){photo.undo.push(snapshot(photo.settings,photo.intensity,photo.recipe));if(photo.undo.length>40)photo.undo.shift();photo.redo=[];photo.settings=normalizeSettings(treatment.settings);photo.intensity=Math.max(0,Math.min(100,Number(treatment.intensity)||0));photo.recipe=clone(treatment.recipe);photo.revision++;}
export function settingsAtIntensity(settings,intensity){const t=intensity/100,p=normalizeSettings(settings);for(const key of Object.keys(p)){if(key==='hsl')p.hsl=p.hsl.map(v=>({h:v.h*t,s:v.s*t,l:v.l*t}));else if(key==='curve')p.curve=p.curve.map((v,i)=>defaults.curve[i]+(v-defaults.curve[i])*t);else if(key!=='grainSize'&&key!=='mono')p[key]*=t;}p.mono=settings.mono?settings.mono*t:0;return p;}
export function uniqueImageNames(photos,type){const used=new Set(),ext=type==='image/png'?'png':'jpg';return photos.map(photo=>{const stem=photo.name.replace(/\.[^.]+$/,'').replace(/[^\p{L}\p{N}_-]/gu,'-')||'foto',recipe=photo.recipe.name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9_-]/g,'-').replace(/-+/g,'-').replace(/^-|-$/g,'').toLowerCase()||'editada';let base=`${stem}-${recipe}`,name=`${base}.${ext}`,i=2;while(used.has(name.toLowerCase()))name=`${base}-${i++}.${ext}`;used.add(name.toLowerCase());return name;});}
export function photoDimensions(width,height,size='original',custom=4000){if(!width||!height)throw new Error('No se pudo leer el tamaño de la fotografía.');const side=size==='original'?Math.max(width,height):size==='2048'?2048:Number(custom);if(!Number.isFinite(side)||(size==='custom'&&side<256))throw new Error('Ingresá un lado mayor de al menos 256 píxeles.');const ratio=Math.min(1,side/Math.max(width,height));return {width:Math.max(1,Math.round(width*ratio)),height:Math.max(1,Math.round(height*ratio))};}
